data.query:
query GetTimezoneAndWorkcenters {
  setting(where: { id: { _eq: "TimeZone" } }) {
    edges {
      node {
        defaultValue
      }
    }
  }
  
  workcenter(
    where: {
      scheduleGroupId: { _isNull: false }
      isActive: { _eq: true }

    }
    first: 1000
  ) {
    edges {
      node {
        id
        code
        name
        scheduleGroupId
        currentWorkcenterHistoryId
      }
    }
  }
}

