'use strict';

// Extract timezone from query result
const settingEdges = $.setting?.edges || [];
let timezone = null;

if (settingEdges.length > 0 && settingEdges[0].node?.defaultValue) {
  timezone = settingEdges[0].node.defaultValue;
  console.log('Using configured timezone: ' + timezone);
} else {
  timezone = $momentTzGuess();
  console.log('No timezone configured, using guess: ' + timezone);
}

// Extract workcenters
const workcenters = $.workcenter?.edges?.map(e => e.node) || [];

console.log('Found ' + workcenters.length + ' active workcenters with schedules');

// Calculate today's boundaries in local timezone
const now = $moment().tz(timezone);
const todayStart = now.clone().startOf('day');
const todayEnd = now.clone();

// Calculate yesterday's boundaries
const yesterdayStart = now.clone().subtract(1, 'day').startOf('day');
const yesterdayEnd = now.clone().subtract(1, 'day').endOf('day');

// Determine if we should calculate yesterday (first 5 minutes of new day)
const minutesIntoDay = now.diff(todayStart, 'minutes');
const shouldCalculateYesterday = minutesIntoDay < 20;

console.log('═══════════════════════════════════════════════════════════');
console.log('OEE Daily Real-time Aggregation - Boundaries Calculated');
console.log('═══════════════════════════════════════════════════════════');
console.log('Timezone: ' + timezone);
console.log('Current Time (local): ' + now.format('YYYY-MM-DD HH:mm:ss'));
console.log('Minutes into day: ' + minutesIntoDay);
console.log('Should calculate yesterday: ' + shouldCalculateYesterday);
console.log('---');
console.log('TODAY:');
console.log('  Date: ' + todayStart.format('YYYY-MM-DD'));
console.log('  Period (local): ' + todayStart.format('YYYY-MM-DD HH:mm:ss') + ' to ' + todayEnd.format('YYYY-MM-DD HH:mm:ss'));

