  console.log('---');
  console.log('YESTERDAY (final calculation):');
  console.log('  Date: ' + yesterdayStart.format('YYYY-MM-DD'));
  console.log('  Period (local): ' + yesterdayStart.format('YYYY-MM-DD HH:mm:ss') + ' to ' + yesterdayEnd.format('YYYY-MM-DD HH:mm:ss'));
}
console.log('═══════════════════════════════════════════════════════════');

// Build array of periods to calculate
