  periods.push({
    name: 'yesterday',
    date: yesterdayStart.format('YYYY-MM-DD'),
    startLocal: yesterdayStart.toISOString(),
    endLocal: yesterdayEnd.toISOString(),
    startUTC: yesterdayStart.clone().utc().toISOString(),
    endUTC: yesterdayEnd.clone().utc().toISOString()
  });
}

