return {
  timezone: timezone,
  workcenters: workcenters,
  workcenterCount: workcenters.length,
  periods: periods,
  shouldCalculateYesterday: shouldCalculateYesterday
};

data.query:
query GetWorkcenterData(
  $workcenterId: String!
  $todayStart: DateTime!
  $todayEnd: DateTime!
) {
  # Return the period identifiers for tracking
  _meta: __type(name: "Query") {
    name
    
  }
  
  # Get workcenter details for code
  workcenter(where: { id: { _eq: $workcenterId } }) {
    edges {
      node {
        id
        code
        name
      }
    }
  }
  
  # Get all WorkcenterHistory for this workcenter that overlaps with period
  workcenterHistory(
    where: {
      workcenterId: { _eq: $workcenterId }
      _and: [
        {
          occurAt: { _lt: $todayEnd }
        }
        {
          _or: [
            { endAt: { _gte: $todayStart } }
            { endAt: { _isNull: true } }
          ]
        }
      ]
    }
    first: 10000
    orderBy: { field: occurAt, direction: asc }
  ) {
    edges {
      node {
        id
        workcenterId
        occurAt
        endAt
        duration(format: milliseconds)
        scheduleId
        modeId
        mode {
          id
          name
          countAsProductionTime
          countAsDowntime
          countAsPlannedDowntime
        }
      }
    }
  }
  
  # Get ProductionLog for this workcenter created during period
  productionLog(
    where: {
      workcenterId: { _eq: $workcenterId }
      occurAt: { _gte: $todayStart, _lte: $todayEnd }
    }
    first: 10000
    orderBy: { field: occurAt, direction: asc }
  ) {
    edges {
      node {
        id
        workcenterId
        occurAt
        quantityGood
        quantityScrap
        cycleTime
        productId
        product {
          standardCycleTime
          idealCycleTime(format: milliseconds)
        }
      }
    }
  }
}

