  }
];

// Add yesterday if within grace period
if (shouldCalculateYesterday) {
  periods.push({
    name: 'yesterday',
    date: yesterdayStart.format('YYYY-MM-DD'),
    startLocal: yesterdayStart.toISOString(),
    endLocal: yesterdayEnd.toISOString(),
    startUTC: yesterdayStart.clone().utc().toISOString(),
    endUTC: yesterdayEnd.clone().utc().toISOString()
  });
}

// Return data for context
return {
  timezone: timezone,
  workcenters: workcenters,
  workcenterCount: workcenters.length,
  periods: periods,
  shouldCalculateYesterday: shouldCalculateYesterday
};

