'use strict';

// ═══════════════════════════════════════════════════════════════════════
// OEE DAILY REAL-TIME AGGREGATION - ISO 22400-2 COMPLIANT
// ═══════════════════════════════════════════════════════════════════════
// 
// TIME CLASSIFICATION LOGIC:
// 1. If scheduleId = null → unscheduledTime (off-shift, not in OEE)
// 2. If scheduleId exists → scheduledTime, then classify by mode:
//    - countAsProduction → operatingTime
//    - countAsPlannedDowntime → plannedDowntime
//    - countAsDowntime → unplannedDowntime
//    - else → idleTime
//
// ISO 22400-2 FORMULAS:
// - Planned Production Time = Scheduled Time - Planned Downtime
// - Availability = (PPT - Unplanned Downtime) / PPT
// - Performance = Ideal Cycle Time / Operating Time
// - Quality = Good Qty / Produced Qty
// - OEE = A × P × Q
//
// ═══════════════════════════════════════════════════════════════════════

console.log('═══════════════════════════════════════════════════════════');
console.log('OEE DAILY AGGREGATION - ISO 22400-2');
console.log('═══════════════════════════════════════════════════════════');

// Get context data
const timezone = $state.context.timezone;
const queryMetadata = $state.context.queryMetadata || [];

console.log('Timezone: ' + timezone);
console.log('Query Metadata Items: ' + queryMetadata.length);

// Input is array of query results (broadcast sends one at a time)
const results = Array.isArray($) ? $ : [$];
console.log('Query Results: ' + results.length);
console.log('═══════════════════════════════════════════════════════════');

// Validate context
if (!timezone || queryMetadata.length === 0) {
  console.error('ERROR: Missing required context data (timezone or queryMetadata)');
  return [];
}

// ═══════════════════════════════════════════════════════════════════════
// HELPER FUNCTIONS
// ═══════════════════════════════════════════════════════════════════════

// Null-safe number conversion
function num(val) {
  if (val === null || val === undefined) return 0;
  const n = Number(val);
  return isNaN(n) ? 0 : n;
}

// Convert duration to milliseconds
function toMs(val) {
  if (!val) return 0;
  if (typeof val === 'number') return val;
  if (typeof val === 'string') {
    try {
      return $momentDuration(val).asMilliseconds();
    } catch (e) {
      console.warn('Cannot parse duration: ' + val);
      return 0;
    }
  }
  return 0;
}

// Get product ideal cycle time: coalesce(idealCycleTime, standardCycleTime * 1000, 0)
function getIdealCycleTimeMs(product) {
  if (!product) return 0;
  
  // Try idealCycleTime first (Duration in ms)
  if (product.idealCycleTime) {
    const ms = toMs(product.idealCycleTime);
    if (ms > 0) return ms;
  }
  
  // Try standardCycleTime (Float in seconds) - convert to ms
  if (product.standardCycleTime && product.standardCycleTime > 0) {
    return product.standardCycleTime * 1000;
  }
  
  return 0;
}

// ═══════════════════════════════════════════════════════════════════════
// PROCESS EACH QUERY RESULT
// ═══════════════════════════════════════════════════════════════════════

const oeeDailyRecords = [];
let processedCount = 0;
let skippedCount = 0;

results.forEach(function(result, idx) {
  
  console.log('──────────────────────────────────────────────────────────');
  console.log('Processing Result #' + idx);
  
  // ───────────────────────────────────────────────────────────────────
  // EXTRACT WORKCENTER INFO FROM QUERY RESULTS
  // ───────────────────────────────────────────────────────────────────
  
  const workcenterNode = result.workcenter?.edges?.[0]?.node;
  if (!workcenterNode) {
    console.warn('  ⚠ No workcenter data in query result, skipping');
    skippedCount++;
    return;
  }
  
  const queryWorkcenterId = workcenterNode.id;
  const queryWorkcenterCode = workcenterNode.code;
  const queryWorkcenterName = workcenterNode.name;
  
  console.log('  Query Workcenter: ' + queryWorkcenterId);
  
  // ───────────────────────────────────────────────────────────────────
  // FIND MATCHING METADATA BY WORKCENTER ID
  // ───────────────────────────────────────────────────────────────────
  
  const metadata = queryMetadata.find(function(m) {
    return m.workcenterId === queryWorkcenterId;
  });
  
  if (!metadata) {
    console.warn('  ⚠ No metadata found for workcenter: ' + queryWorkcenterId);
    console.warn('  Available metadata workcenter IDs: ' + queryMetadata.slice(0, 5).map(function(m) { return m.workcenterId; }).join(', ') + '...');
    skippedCount++;
    return;
  }
  
  // Extract period information from metadata
  const periodDate = metadata.todayDate;
  const periodStart = metadata.todayStart;
  const periodEnd = metadata.todayEnd;
  const periodName = metadata.periodName;
  
  // Use query data for workcenter info (with metadata as fallback)
  const workcenterId = queryWorkcenterId;
  const workcenterCode = queryWorkcenterCode || metadata.workcenterCode || workcenterId;
  const workcenterName = queryWorkcenterName || metadata.workcenterName || '';
  
  // Validate required fields
  if (!workcenterId || !periodDate || !periodStart || !periodEnd) {
    console.warn('  ⚠ Missing required fields, skipping');
    console.warn('    workcenterId: ' + workcenterId);
    console.warn('    periodDate: ' + periodDate);
    skippedCount++;
    return;
  }
  
  console.log('  Workcenter: ' + workcenterCode + ' (' + workcenterId + ')');
  if (workcenterName) {
    console.log('  Name: ' + workcenterName);
  }
  console.log('  Period: ' + periodName + ' (' + periodDate + ')');
  
  // Create moment objects for period boundaries
  const periodStartMoment = $moment(periodStart).utc();
  const periodEndMoment = $moment(periodEnd).utc();
  
  console.log('  Range: ' + periodStartMoment.format('MM-DD HH:mm') + ' to ' + periodEndMoment.format('MM-DD HH:mm'));
  
  // ───────────────────────────────────────────────────────────────────
  // EXTRACT QUERY RESULTS
  // ───────────────────────────────────────────────────────────────────
  
  const historyRecords = (result.workcenterHistory?.edges || []).map(function(e) { return e.node; });
  const productionLogs = (result.productionLog?.edges || []).map(function(e) { return e.node; });
  
  console.log('  History Records: ' + historyRecords.length);
  console.log('  Production Logs: ' + productionLogs.length);
  
  // ───────────────────────────────────────────────────────────────────
  // CALCULATE TIME METRICS FROM WORKCENTER HISTORY
  // ───────────────────────────────────────────────────────────────────
  
  // Time classification buckets
  let scheduledTimeMs = 0;        // Time WITH scheduleId
  let unscheduledTimeMs = 0;      // Time WITHOUT scheduleId (off-shift, excluded from OEE)
  let operatingTimeMs = 0;        // Production time (ISO: Operating Time)
  let plannedDowntimeMs = 0;      // Scheduled breaks/maintenance (within scheduled time)
  let unplannedDowntimeMs = 0;    // Unscheduled stops/failures (within scheduled time)
  let idleTimeMs = 0;             // Minor stops, speed loss (within scheduled time)
  
  const schedulesUsed = new Set();
  
  historyRecords.forEach(function(record) {
    
    // Validate record has mode
    if (!record.mode) {
      console.warn('    ⚠ Skipping history record without mode: ' + record.id);
      return;
    }
    
    // Determine effective start and end times
    const occurAt = $moment(record.occurAt).utc();
    
    let endAt;
    if (record.endAt === null || record.endAt === undefined) {
      // Active record (still in progress) - use period end
      endAt = periodEndMoment.clone();
    } else {
      endAt = $moment(record.endAt).utc();
    }
    
    // Clip to period boundaries
    const effectiveStart = $momentMax([occurAt, periodStartMoment]);
    const effectiveEnd = $momentMin([endAt, periodEndMoment]);
    
    // Calculate duration within this period
    const durationMs = effectiveEnd.diff(effectiveStart, 'milliseconds');
    
    // Skip if no overlap with period
    if (durationMs <= 0) {
      return;
    }
    
    // ═══════════════════════════════════════════════════════════════════
    // TIME CLASSIFICATION LOGIC
    // ═══════════════════════════════════════════════════════════════════
    
    const hasSchedule = record.scheduleId && record.scheduleId !== null && record.scheduleId !== '';
    const mode = record.mode;
    
    if (!hasSchedule) {
      // ─────────────────────────────────────────────────────────────────
      // NO SCHEDULE = UNSCHEDULED TIME (OFF-SHIFT)
      // ─────────────────────────────────────────────────────────────────
      // Excluded from OEE calculation
      // Mode flags are ignored when there's no schedule
      unscheduledTimeMs += durationMs;
      
    } else {
      // ─────────────────────────────────────────────────────────────────
      // HAS SCHEDULE = SCHEDULED TIME
      // ─────────────────────────────────────────────────────────────────
      // Included in OEE calculation
      // Classify by mode flags
      
      scheduledTimeMs += durationMs;
      schedulesUsed.add(record.scheduleId);
      
      // Classify within scheduled time by mode flags (ISO 22400-2)
      if (mode.countAsProduction || mode.countAsProductionTime) {
        // Operating Time: Machine running and producing
        operatingTimeMs += durationMs;
        
      } else if (mode.countAsPlannedDowntime) {
        // Planned Downtime: Scheduled breaks, maintenance, changeovers
        plannedDowntimeMs += durationMs;
        
      } else if (mode.countAsDowntime) {
        // Unplanned Downtime: Breakdowns, failures
        unplannedDowntimeMs += durationMs;
        
      } else {
        // Idle Time: Minor stops, speed loss, unclassified
        idleTimeMs += durationMs;
      }
    }
  });
  
  console.log('  Time Classification (hours):');
  console.log('    Scheduled: ' + (scheduledTimeMs / 3600000).toFixed(2) + 'h');
  console.log('    Unscheduled: ' + (unscheduledTimeMs / 3600000).toFixed(2) + 'h');
  console.log('    └─ Operating: ' + (operatingTimeMs / 3600000).toFixed(2) + 'h');
  console.log('    └─ Planned DT: ' + (plannedDowntimeMs / 3600000).toFixed(2) + 'h');
  console.log('    └─ Unplanned DT: ' + (unplannedDowntimeMs / 3600000).toFixed(2) + 'h');
  console.log('    └─ Idle: ' + (idleTimeMs / 3600000).toFixed(2) + 'h');
  
  // ───────────────────────────────────────────────────────────────────
  // CALCULATE PRODUCTION METRICS FROM PRODUCTION LOG
  // ───────────────────────────────────────────────────────────────────
  
  let producedQty = 0;           // ISO: PQ (Produced Quantity)
  let goodQty = 0;               // ISO: GQ (Good Quantity)
  let scrapQty = 0;              // Scrap/Reject quantity
  let actualCycleTimeMs = 0;     // Total actual time spent producing
  let idealCycleTimeMs = 0;      // Total ideal time (theoretical minimum)
  
  productionLogs.forEach(function(log) {
    
    const good = num(log.quantityGood);
    const scrap = num(log.quantityScrap);
    const qty = good + scrap;
    
    producedQty += qty;
    goodQty += good;
    scrapQty += scrap;
    
    // Actual cycle time from log (in seconds, convert to ms)
    if (log.cycleTime && qty > 0) {
      actualCycleTimeMs += log.cycleTime * 1000 * qty;
    }
    
    // Ideal cycle time from product
    if (log.product && qty > 0) {
      const idealPerUnit = getIdealCycleTimeMs(log.product);
      idealCycleTimeMs += idealPerUnit * qty;
    }
  });
  
  console.log('  Production Metrics:');
  console.log('    Produced: ' + producedQty + ' units');
  console.log('    Good: ' + goodQty + ' units');
  console.log('    Scrap: ' + scrapQty + ' units');
  
  // ───────────────────────────────────────────────────────────────────
  // CALCULATE ISO 22400-2 OEE METRICS
  // ───────────────────────────────────────────────────────────────────
  
  // ISO 22400-2 Formula 1: Planned Production Time (PBT)
  // PBT = Scheduled Time - Planned Downtime
  const plannedProductionTimeMs = Math.max(0, scheduledTimeMs - plannedDowntimeMs);
  
  // Total downtime (for reporting)
  const totalDowntimeMs = plannedDowntimeMs + unplannedDowntimeMs;
  
  // ISO 22400-2 Formula 2: Availability
  // A = (Planned Production Time - Unplanned Downtime) / Planned Production Time
  let availability = 0;
  if (plannedProductionTimeMs > 0) {
    const availableTimeMs = Math.max(0, plannedProductionTimeMs - unplannedDowntimeMs);
    availability = availableTimeMs / plannedProductionTimeMs;
    availability = Math.max(0, Math.min(1, availability)); // Clamp to [0,1]
  }
  
  // ISO 22400-2 Formula 3: Performance
  // P = (Ideal Cycle Time × Produced Quantity) / Operating Time
  let performance = 0;
  if (operatingTimeMs > 0 && idealCycleTimeMs > 0) {
    performance = idealCycleTimeMs / operatingTimeMs;
    performance = Math.max(0, Math.min(1, performance)); // Clamp to [0,1]
  }
  
  // ISO 22400-2 Formula 4: Quality
  // Q = Good Quantity / Produced Quantity
  let quality = 1; // Default 100% if no production (no defects created)
  if (producedQty > 0) {
    quality = goodQty / producedQty;
    quality = Math.max(0, Math.min(1, quality)); // Clamp to [0,1]
  }
  
  // ISO 22400-2 Formula 5: OEE
  // OEE = Availability × Performance × Quality
  const oee = availability * performance * quality;
  
  console.log('  OEE Metrics:');
  console.log('    Availability: ' + (availability * 100).toFixed(1) + '%');
  console.log('    Performance: ' + (performance * 100).toFixed(1) + '%');
  console.log('    Quality: ' + (quality * 100).toFixed(1) + '%');
  console.log('    OEE: ' + (oee * 100).toFixed(1) + '%');
  
  // ───────────────────────────────────────────────────────────────────
  // CALCULATE DERIVED METRICS
  // ───────────────────────────────────────────────────────────────────
  
  // Ideal units (how many could have been produced in operating time)
  const avgIdealCycleTime = producedQty > 0 ? idealCycleTimeMs / producedQty : 0;
  const idealUnits = (avgIdealCycleTime > 0 && operatingTimeMs > 0) 
    ? operatingTimeMs / avgIdealCycleTime 
    : 0;
  
  // Average actual cycle time per unit
  const avgActualCycleTime = producedQty > 0 ? actualCycleTimeMs / producedQty : 0;
  
  // Build schedules metadata
  const schedules = {
    scheduleIds: Array.from(schedulesUsed),
    primaryScheduleId: Array.from(schedulesUsed)[0] || null
  };
  
  // Hours metrics
  const hoursRecorded = Math.round(scheduledTimeMs / 3600000);
  const hoursWithProduction = productionLogs.length > 0 ? 1 : 0;
  
  // ───────────────────────────────────────────────────────────────────
  // CREATE OEEDAILY RECORD
  // ───────────────────────────────────────────────────────────────────
  
  const recordId = workcenterCode + '-' + periodDate;
  
  const record = {
    // Identity
    id: recordId,
    workcenterId: workcenterId,
    
    // Period
    periodStartAt: periodStart,
    periodEndAt: periodEnd,
    periodDayAt: periodDate,
    
    // Quantities
    totalUnits: producedQty,
    goodUnits: goodQty,
    scrapUnits: scrapQty,
    idealUnits: Math.round(idealUnits * 100) / 100,
    
    // Time Durations (all in milliseconds, all positive)
    scheduledTime: Math.max(0, Math.round(scheduledTimeMs)),
    unscheduledTime: Math.max(0, Math.round(unscheduledTimeMs)),
    runMinutes: Math.max(0, Math.round(operatingTimeMs)),
    plannedProductionTime: Math.max(0, Math.round(plannedProductionTimeMs)),
    actualProductionTime: Math.max(0, Math.round(operatingTimeMs)),
    idleTime: Math.max(0, Math.round(idleTimeMs)),
    downtimeTotal: Math.max(0, Math.round(totalDowntimeMs)),
    downtimeUnplanned: Math.max(0, Math.round(unplannedDowntimeMs)),
    downtimePlanned: Math.max(0, Math.round(plannedDowntimeMs)),
    actualCycleTime: Math.max(0, Math.round(actualCycleTimeMs)),
    idealCycleTime: Math.max(0, Math.round(idealCycleTimeMs)),
    averageActualCycleTime: Math.max(0, Math.round(avgActualCycleTime)),
    
    // OEE Metrics (0-1 range, 4 decimal places)
    availability: Math.round(availability * 10000) / 10000,
    performance: Math.round(performance * 10000) / 10000,
    quality: Math.round(quality * 10000) / 10000,
    oee: Math.round(oee * 10000) / 10000,
    
    // Metadata
    hoursRecorded: hoursRecorded,
    hoursWithProduction: hoursWithProduction,
    schedules: schedules
  };
  
  oeeDailyRecords.push(record);
  processedCount++;
  console.log('  ✓ Created record: ' + recordId);
});

console.log('═══════════════════════════════════════════════════════════');
console.log('SUMMARY:');
console.log('  Processed: ' + processedCount + ' records');
console.log('  Skipped: ' + skippedCount + ' records');
console.log('  Total OeeDaily records: ' + oeeDailyRecords.length);
console.log('═══════════════════════════════════════════════════════════');

return oeeDailyRecords.length > 0 ? oeeDailyRecords : [];
